// SPDX-License-Identifier: MIT
pragma solidity =0.8.23;

/**
 * @title IFeeCollector
 * @notice Defines the basic interface for the FeeCollector contract.
 */
interface IFeeCollector {
    /**
     * @dev Struct for storing fee records of specific collateral asset.
     * @param from The timestamp in seconds when the decay of refundable fee started.
     * @param to The timestamp in seconds when the decay of refundable fee expired.
     * @param _amount The amount of refundable fee.
     */
    struct FeeRecord {
        uint256 from;
        uint256 to;
        uint256 amount;
    }

    /**
     * @dev Emitted when the fee record is updated.
     * @param _borrower The address of borrower.
     * @param _asset The address of collateral asset.
     * @param _from The timestamp in seconds when the decay of refundable fee started.
     * @param _to The timestamp in seconds when the decay of refundable fee expired.
     * @param _amount The amount of refundable fee
     */
    event FeeRecordUpdated(
        address indexed _borrower,
        address indexed _asset,
        uint256 _from,
        uint256 _to,
        uint256 _amount
    );

    /**
     * @dev Emitted when the collected fees are transferred to either the treasury
     * or the TRENStaking contract.
     * @param _borrower The address of borrower.
     * @param _asset The address of collateral asset.
     * @param _collector The address of destination.
     * @param _amount The amount of collected fees (debt tokens).
     */
    event FeeCollected(
        address indexed _borrower,
        address indexed _asset,
        address indexed _collector,
        uint256 _amount
    );

    /**
     * @dev Emitted when the fees are refunded to the borrower.
     * @param _borrower The address of borrower.
     * @param _asset The address of collateral asset.
     * @param _amount The amount of refunded fees.
     */
    event FeeRefunded(address indexed _borrower, address indexed _asset, uint256 _amount);

    /**
     * @dev Emitted when the redemption fees are collected.
     * @param _asset The address of collateral asset.
     * @param _amount The amount of collected fees.
     */
    event RedemptionFeeCollected(address indexed _asset, uint256 _amount);

    /**
     * @dev Emitted when the TRENStaking address is set.
     * @param _trenStaking The address of TRENStaking contract.
     */
    event TRENStakingAddressSet(address _trenStaking);

    /**
     * @dev Emitted when the lengths of array parameters are mismatched.
     */
    error FeeCollector__ArrayMismatch();

    /**
     * @dev Emitted when the caller is not BorrowerOperations.
     * @param _sender The address of caller.
     * @param _expected The address of BorrowerOperations.
     */
    error FeeCollector__BorrowerOperationsOnly(address _sender, address _expected);

    /**
     * @dev Emitted when the caller is neither BorrowerOperations nor TrenBoxManager.
     * @param _sender The address of caller.
     * @param _expected1 The address of BorrowerOperations.
     * @param _expected2 The address of TrenBoxManager.
     */
    error FeeCollector__BorrowerOperationsOrTrenBoxManagerOnly(
        address _sender, address _expected1, address _expected2
    );

    /**
     * @dev Emitted when the caller is not TrenBoxManager.
     * @param _sender The address of caller.
     * @param _expected The address of TrenBoxManager.
     */
    error FeeCollector__TrenBoxManagerOnly(address _sender, address _expected);

    /**
     * @dev Emitted when the payback fraction is higher than 1 ether(10**18 wei).
     */
    error FeeCollector__PaybackFractionHigherThanOne();

    /**
     * @dev Emitted when the payback fraction is zero.
     */
    error FeeCollector__ZeroPaybackFraction();

    /**
     * @dev Emitted when trying to set TRENStaking with zero address.
     */
    error FeeCollector__TRENStakingZeroAddress();

    /**
     * @notice Increases debt of fee amount when a TrenBox is created and again
     * whenever the borrower acquires additional loans.
     * Collects the minimum fee to the platform, for which there is no refund; holds on to the
     * remaining fees until debt is paid, liquidated, or expired.
     * @dev Attention: this method assumes that (debt token) _feeAmount has already been minted and
     * transferred to this contract.
     * @param _borrower The address of borrower.
     * @param _asset The address of collateral asset.
     * @param _feeAmount The fee amount to collect.
     */
    function increaseDebt(address _borrower, address _asset, uint256 _feeAmount) external;

    /**
     * @notice Decreases debt when a TrenBox is adjusted.
     * @param _borrower The address of borrower.
     * @param _asset The address of collateral asset.
     * @param _paybackFraction The amount that the borrower pays back.
     */
    function decreaseDebt(address _borrower, address _asset, uint256 _paybackFraction) external;

    /**
     * @notice Closes debt when it is paid in full.
     * @param _borrower The address of borrower.
     * @param _asset The address of collateral asset.
     */
    function closeDebt(address _borrower, address _asset) external;

    /**
     * @notice Triggered when a TrenBox is liquidated. In that case, all remaining fees are
     * collected by the platform, and no refunds are generated.
     * @param _borrower The address of borrower.
     * @param _asset The address of collateral asset.
     */
    function liquidateDebt(address _borrower, address _asset) external;

    /**
     * @notice Simulates the refund due if a TrenBox would be closed at this moment
     * @dev Helper function used by the UI.
     * @param _borrower The address of borrower.
     * @param _asset The address of collateral asset.
     * @param _paybackFraction The amount that the borrower pays back.
     */
    function simulateRefund(
        address _borrower,
        address _asset,
        uint256 _paybackFraction
    )
        external
        returns (uint256);

    /**
     * @notice Batches collect fees from an array of borrowers and assets.
     * @param _borrowers The address array of borrowers.
     * @param _assets The address array of collateral assets.
     */
    function collectFees(address[] calldata _borrowers, address[] calldata _assets) external;

    /**
     * @notice Sends redemption fee to the protocol revenue destination.
     * @param _asset The address of collateral asset.
     * @param _amount The amount of redemption fee to send.
     */
    function handleRedemptionFee(address _asset, uint256 _amount) external;

    /**
     * @notice Gets the protocol revenue destination.
     */
    function getProtocolRevenueDestination() external view returns (address);

    /**
     * @notice Gets the TRENStaking address.
     */
    function trenStaking() external view returns (address);
}

contracts/interfaces/IStabilityPool.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity =0.8.23;

import { IDeposit } from "./IDeposit.sol";

/**
 * @title IStabilityPool
 * @notice Defines the basic interface for StabilityPool contract.
 */
interface IStabilityPool is IDeposit {
    // --- Structs ---

    /**
     * @dev Struct for tracking a depositor's snapshot.
     * @param S The sum of collateral gains.
     * @param P The product.
     * @param G The sum of TREN gains.
     * @param scale The current scale.
     * @param epoch The current epoch.
     */
    struct Snapshots {
        mapping(address => uint256) S;
        uint256 P;
        uint256 G;
        uint128 scale;
        uint128 epoch;
    }

    // --- Events ---

    /**
     * @dev Emitted when the snapshot for a specific depositor is updated.
     * @param _depositor The caller address.
     * @param _P The product.
     * @param _G The sum of TREN gains.
     */
    event DepositSnapshotUpdated(address indexed _depositor, uint256 _P, uint256 _G);

    /**
     * @dev Emitted when collateral gains are transferred to a depositor.
     * @param _depositor The depositor address.
     * @param _collaterals The address array of collaterals gained.
     * @param _amounts The amount array of collaterals gained.
     * @param _debtTokenLoss The loss of debt tokens against initial deposit.
     */
    event GainsWithdrawn(
        address indexed _depositor,
        address[] _collaterals,
        uint256[] _amounts,
        uint256 _debtTokenLoss
    );

    /**
     * @dev Emitted when TREN gains are transferred to a depositor.
     * @param _depositor The depositor address.
     * @param _TREN The amount of TREN tokens.
     */
    event TRENPaidToDepositor(address indexed _depositor, uint256 _TREN);

    /**
     * @dev Emitted when the specific collateral is received from trenBoxStorage contract.
     * @param _asset The address of collateral asset.
     * @param _newBalance The updated balance of collateral asset.
     */
    event StabilityPoolAssetBalanceUpdated(address _asset, uint256 _newBalance);

    /**
     * @dev Emitted when debt tokens are sent to a user or moved to other pool.
     * @param _newBalance The updated balance of debt tokens.
     */
    event StabilityPoolDebtTokenBalanceUpdated(uint256 _newBalance);

    /**
     * @dev Emitted when a user deposits or withdraws debt tokens.
     * @param _depositor The depositor address.
     * @param _newDeposit The updated user balance.
     */
    event UserDepositChanged(address indexed _depositor, uint256 _newDeposit);

    /**
     * @dev Emitted when the product is updated.
     * @param _P The new product.
     */
    event ProductUpdated(uint256 _P);

    /**
     * @dev Emitted when the sum is updated.
     * @param _asset The address of collateral asset.
     * @param _S The new sum of collateral gains.
     * @param _epoch The current epoch.
     * @param _scale THe current scale.
     */
    event SumUpdated(address _asset, uint256 _S, uint128 _epoch, uint128 _scale);

    /**
     * @dev Emitted when the sum of TREN gains is updated.
     * @param _G The new sum of TREN gains.
     * @param _epoch The current epoch.
     * @param _scale The current scale.
     */
    event GainsUpdated(uint256 _G, uint128 _epoch, uint128 _scale);

    /**
     * @dev Emitted when the current epoch is updated.
     * @param _currentEpoch The new epoch.
     */
    event EpochUpdated(uint128 _currentEpoch);

    /**
     * @dev Emitted when the current scale is updated.
     * @param _currentScale The new scale.
     */
    event ScaleUpdated(uint128 _currentScale);

    // --- Errors ---

    /**
     * @dev Error emitted when the caller is not TrenBoxStorage.
     * @param _sender The caller address.
     * @param _expected The TrenBoxStorage address.
     */
    error StabilityPool__TrenBoxStorageOnly(address _sender, address _expected);

    /**
     * @dev Error emitted when the caller is not AdminContract.
     * @param _sender The caller address.
     * @param _expected The AdminContract address.
     */
    error StabilityPool__AdminContractOnly(address _sender, address _expected);

    /**
     * @dev Error emitted when the caller is not TrenBoxManager.
     * @param _sender The caller address.
     * @param _expected The TrenBoxManager address.
     */
    error StabilityPool__TrenBoxManagerOnly(address _sender, address _expected);

    /// @dev Error emitted when the asset list is not in ascending order.
    error StabilityPool__ArrayNotInAscendingOrder();

    /// @dev Error emitted when the user should wait for 7 days after deposit.
    error StabilityPool__ShouldWaitFor7DaysAfterDeposit();

    /**
     * @dev Error emitted when the debt loss per unit staked is not less than
     * decimal precision.
     * @param _debtLoss The debt loss per unit staked.
     */
    error StabilityPool__DebtLossBelowOne(uint256 _debtLoss);

    /// @dev Error emitted when the amount of debt to offset is larger than
    /// total deposits.
    error StabilityPool__DebtLargerThanTotalDeposits();

    /// @dev Error emitted when the new product is zero.
    error StabilityPool__ProductZero();

    /// @dev Error emitted when the array length is mismatched.
    error StabilityPool__AssetsAndAmountsLengthMismatch();

    /// @dev Error emitted when the user's initial deposit is zero.
    error StabilityPool__UserHasNoDeposit();

    /// @dev Error emitted when the amount is zero.
    error StabilityPool__AmountMustBeNonZero();

    // --- Functions ---

    /**
     * @notice Gets collateral balance in the Stability Pool for a given collateral type.
     * @dev Not necessarily this contract's actual collateral balance;
     * just what is stored in state
     * @param _collateral The address of collateral asset.
     * @return The amount of collateral asset.
     */
    function getCollateral(address _collateral) external view returns (uint256);

    /**
     * @notice Gets all collateral assets and amounts.
     */
    function getAllCollateral() external view returns (address[] memory, uint256[] memory);

    /**
     * @notice Returns total deposits of debt tokens held in the pool.
     * Changes when users deposit/withdraw, and when a TrenBox debt is offset.
     */
    function getTotalDebtTokenDeposits() external view returns (uint256);

    /**
     * @notice Calculates the gains earned by a deposit since its last snapshots were taken for
     * selected assets.
     * @dev Given by the formula: E = d0 * (S - S(0))/P(0),
     * where S(0) and P(0) are the depositor's snapshots of the sum S and product P, respectively.
     * d0 is the last recorded deposit value.
     * @param _depositor The depositor address.
     * @param _assets The array of collateral assets to check gains for.
     */
    function getDepositorGains(
        address _depositor,
        address[] calldata _assets
    )
        external
        view
        returns (address[] memory, uint256[] memory);

    /**
     * @notice Calculates the TREN gain earned by a deposit since its last snapshots were taken.
     * @dev Given by the formula: TREN = d0 * (G - G(0))/P(0),
     * where G(0) and P(0) are the depositor's snapshots of the sum G and product P, respectively.
     * d0 is the last recorded deposit value.
     * @param _depositor The depositor address.
     */
    function getDepositorTRENGain(address _depositor) external view returns (uint256);

    /**
     * @notice Returns the user's compounded deposit.
     * @dev Given by the formula: d = d0 * P/P(0),
     * where P(0) is the depositor's snapshot of the product P, taken when they last updated their
     * deposit.
     * @param _depositor The depositor address.
     */
    function getCompoundedDebtTokenDeposits(address _depositor) external view returns (uint256);

    /**
     * @notice Adds new collateral type.
     * @param _collateral The address of collateral asset to add.
     */
    function addCollateralType(address _collateral) external;

    /**
     * @notice Provides debt tokens to the Stability Pool.
     * @dev Triggers a TREN issuance, based on time passed since the last issuance.
     * The TREN issuance is shared between all depositors.
     * - Sends depositor's accumulated gains (TREN, collateral assets) to depositor.
     * - Increases deposit stake, and takes new snapshots for each.
     * Skipping a collateral forfeits the available rewards (can be useful for gas optimizations).
     * @param _amount The amount of debt tokens provided.
     * @param _assets The array of collateral assets to be claimed.
     */
    function provideToSP(uint256 _amount, address[] calldata _assets) external;

    /**
     * @notice Withdraws debt tokens from the Stability Pool.
     * @dev Triggers a TREN issuance, based on time passed since the last issuance.
     * The TREN issuance is shared between all depositors.
     * - Sends all depositor's accumulated gains (TREN, assets) to depositor
     * - Decreases deposit's stake, and takes new snapshots.
     * If _amount > userDeposit, the user withdraws all of their compounded deposit.
     * @param _amount The amount of debt tokens to withdraw.
     * @param _assets The array of collateral assets to be claimed.
     */
    function withdrawFromSP(uint256 _amount, address[] calldata _assets) external;

    /**
     * @notice Sets the offset for liquidation.
     * @dev Cancels out the specified debt against the debt tokens contained in the
     * Stability Pool (as far as possible)
     * and transfers the TrenBox's collateral from TrenBoxStorage to Stability Pool.
     * Only called by liquidation functions in the TrenBoxManager.
     * @param _debtToOffset The amount of debt tokens to offset.
     * @param _asset The address of collateral asset.
     * @param _amountAdded The amount of collateral asset to be added.
     */
    function offset(uint256 _debtToOffset, address _asset, uint256 _amountAdded) external;
}

contracts/interfaces/ITrenBoxStorage.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity =0.8.23;

/**
 * @title ITrenBoxStorage
 * @notice Defines the basic interface for TrenBoxStorage contract.
 */
interface ITrenBoxStorage {
    // ------------------------------------------ Structs -----------------------------------------

    /// @dev Struct for storing debt balances of a specific collateral asset.
    /// @param active The entire debt of all active TrenBoxes.
    /// @param liquidated The entire debt of all liquidated TrenBoxes.
    struct DebtBalances {
        uint256 active;
        uint256 liquidated;
    }

    /// @dev Struct for storing balances of a specific collateral asset.
    /// @param active The entire collateral amount of all active TrenBoxes.
    /// @param liquidated The entire collateral amount of all liquidated TrenBoxes.
    /// @param claimable The entire collateral amount of all liquidated TrenBoxes that can be
    /// claimed by user.
    struct CollBalances {
        uint256 active;
        uint256 liquidated;
        uint256 claimable;
    }

    // ------------------------------------------ Events ------------------------------------------

    /**
     * @dev Emitted when the active collateral balance is updated.
     * @param _collateral The address of the collateral asset.
     * @param _newBalance The new active collateral balance.
     */
    event ActiveCollateralBalanceUpdated(address indexed _collateral, uint256 _newBalance);

    /**
     * @dev Emitted when the active debt balance is updated.
     * @param _collateral The address of the collateral asset.
     * @param _newBalance The new active debt balance.
     */
    event ActiveDebtBalanceUpdated(address indexed _collateral, uint256 _newBalance);

    /**
     * @dev Emitted when the liquidated collateral balance is updated.
     * @param _collateral The address of the collateral asset.
     * @param _newBalance The new liquidated collateral balance.
     */
    event LiquidatedCollateralBalanceUpdated(address indexed _collateral, uint256 _newBalance);

    /**
     * @dev Emitted when the liquidated debt balance is updated.
     * @param _collateral The address of the collateral asset.
     * @param _newBalance The new liquidated debt balance.
     */
    event LiquidatedDebtBalanceUpdated(address indexed _collateral, uint256 _newBalance);

    /**
     * @dev Emitted when the claimable collateral balance is updated.
     * @param _collateral The address of the collateral asset.
     * @param _newBalance The new claimable collateral balance.
     */
    event ClaimableCollateralBalanceUpdated(address indexed _collateral, uint256 _newBalance);

    /**
     * @dev Emitted when collateral is sent.
     * @param _to The address of the user which get collateral amount.
     * @param _collateral The address of the collateral asset.
     * @param _amount The amount of collateral sent.
     */
    event CollateralSent(address indexed _to, address indexed _collateral, uint256 _amount);

    /**
     * @dev Emitted when the user claimable collateral balance is updated.
     * @param _account The address of the user.
     * @param _collateral The address of the collateral asset.
     * @param _newBalance The new user claimable collateral balance.
     */
    event UserClaimableCollateralBalanceUpdated(
        address indexed _account, address indexed _collateral, uint256 _newBalance
    );

    // ------------------------------------------ Custom Errors -----------------------------------

    /**
     * @dev Thrown when contract is not authorized.
     */
    error TrenBoxStorage__NotAuthorizedContract();

    /**
     * @dev Thrown when caller is not TrenBoxManager contract.
     */
    error TrenBoxStorage__TrenBoxManagerOnly();

    /**
     * @dev Thrown when caller is not BorrowerOperations contract.
     */
    error TrenBoxStorage__BorrowerOperationsOnly();

    /**
     * @dev Thrown when caller is not BorrowerOperations nor SwapManager contract.
     */
    error TrenBoxStorage__BorrowerOperationsOrSwapManagerOnly();

    /**
     * @dev Thrown when caller is not BorrowerOperations nor TrenBoxManager contract.
     */
    error TrenBoxStorage__BorrowerOperationsOrTrenBoxManagerOnly();

    /**
     * @dev Thrown when caller is not TrenBoxManagerOperations contract.
     */
    error TrenBoxStorage__TrenBoxManagerOperationsOnly();

    /**
     * @dev Thrown when there is no claimable collateral available.
     */
    error TrenBoxStorage__NoClaimableCollateral();

    // ------------------------------------------ Functions ---------------------------------------

    /**
     * @notice Returns the active collateral balance for a specific collateral asset.
     * @param _collateral The address of the collateral asset.
     */
    function getActiveCollateralBalance(address _collateral) external view returns (uint256);

    /**
     * @notice Returns the active debt balance for a specific collateral asset.
     * @param _collateral The address of the collateral asset.
     */
    function getActiveDebtBalance(address _collateral) external view returns (uint256);

    /**
     * @notice Returns the liquidated collateral balance for a specific collateral asset.
     * @param _collateral The address of the collateral asset.
     */
    function getLiquidatedCollateralBalance(address _collateral) external view returns (uint256);

    /**
     * @notice Returns the liquidated debt balance for a specific collateral asset.
     * @param _collateral The address of the collateral asset.
     */
    function getLiquidatedDebtBalance(address _collateral) external view returns (uint256);

    /**
     * @notice Returns sum of active and liquidated debt for a specific collateral asset.
     * @param _collateral The address of the collateral asset.
     */
    function getTotalDebtBalance(address _collateral) external view returns (uint256);

    /**
     * @notice Returns sum of active and liquidated amount of a specific collateral asset.
     * @param _collateral The address of the collateral asset.
     */
    function getTotalCollateralBalance(address _collateral) external view returns (uint256);

    /**
     * @notice Returns the claimable collateral balance for a specific collateral asset.
     * @param _collateral The address of the collateral asset.
     */
    function getClaimableCollateralBalance(address _collateral) external view returns (uint256);

    /**
     * @notice Returns the claimable collateral balance for a specific user.
     * @param _collateral The address of the collateral asset.
     * @param _account The address of the user.
     */
    function getUserClaimableCollateralBalance(
        address _collateral,
        address _account
    )
        external
        view
        returns (uint256);

    /**
     * @notice Increases the active debt balance for a specific collateral asset.
     * @param _collateral The address of the collateral asset.
     * @param _amount The amount to increase the debt balance.
     */
    function increaseActiveDebt(address _collateral, uint256 _amount) external;

    /**
     * @notice Decreases the active debt balance for a specific collateral asset.
     * @param _collateral The address of the collateral asset.
     * @param _amount The amount to decrease the debt balance.
     */
    function decreaseActiveDebt(address _collateral, uint256 _amount) external;

    /**
     * @notice Increases the active balance for a specific collateral asset.
     * @param _collateral The address of the collateral asset.
     * @param _amount The amount to increase the debt balance.
     */
    function increaseActiveCollateral(address _collateral, uint256 _amount) external;

    /**
     * @notice Decreases the active balance for a specific collateral asset.
     * @param _collateral The address of the collateral asset.
     * @param _amount The amount to decrease the collateral balance.
     */
    function decreaseActiveCollateral(address _collateral, uint256 _amount) external;

    /**
     * @notice Update appropriate data for a specific collateral.
     * @param data The data to update.
     */
    function update(bytes memory data) external;

    /**
     * @notice Updates the active and liquidated debt and collateral balances.
     * @param _collateral The address of the collateral asset.
     * @param _debtAmount The amount to decrease the debt balance.
     * @param _collAmount The amount to decrease the collateral balance.
     * @param _isActiveIncrease The indicator that shows increasing or decreasing of active
     * balances.
     */
    function updateDebtAndCollateralBalances(
        address _collateral,
        uint256 _debtAmount,
        uint256 _collAmount,
        bool _isActiveIncrease
    )
        external;

    /**
     * @notice Updates the entire and user claimable balance for a specific collateral asset.
     * @param _collateral The address of the collateral asset.
     * @param _account The address of the user.
     * @param _amount The amount to update the claimable balance.
     */
    function updateUserAndEntireClaimableBalance(
        address _collateral,
        address _account,
        uint256 _amount
    )
        external;

    /**
     * @notice Increases the claimable collateral balance for a specific collateral asset.
     * @param _collateral The address of the collateral asset.
     * @param _amount The amount to increase the claimable collateral balance.
     */
    function increaseClaimableCollateral(address _collateral, uint256 _amount) external;

    /**
     * @notice Updates the claimable collateral balance of the user for a specific collateral asset.
     * @param _collateral The address of the collateral asset.
     * @param _account The address of the user.
     * @param _amount The amount to update the claimable balance.
     */
    function updateUserClaimableBalance(
        address _collateral,
        address _account,
        uint256 _amount
    )
        external;

    /**
     * @notice Sends amount of active collateral from contract to user.
     * @param _collateral The address of the collateral asset.
     * @param _account The address of the user to send.
     * @param _amount The amount of the collateral to send.
     */
    function sendCollateral(address _collateral, address _account, uint256 _amount) external;

    /**
     * @notice Sends amount of claimable collateral from contract to user.
     * @param _collateral The address of the collateral asset.
     * @param _account The address of the user to send.
     */
    function claimCollateral(address _collateral, address _account) external;
}
